20	class BranchCtrl extends Bundle{
21	  val wid=UInt(depth_warp.W)
22	  val jump=Bool()
23	  val new_pc=UInt(32.W)
24	  val spike_info = if (SPIKE_OUTPUT) Some(new InstWriteBack) else None
