26	class ALUexe extends Module{
27	  val io = IO(new Bundle() {
28	    val in = Flipped(DecoupledIO(new sExeData()))
29	    val out = DecoupledIO(new WriteScalarCtrl())
30	    val out2br = DecoupledIO(new BranchCtrl())
31	  })
32	  val alu=Module(new ScalarALU())
33	  alu.io.in1:=io.in.bits.in1
34	  alu.io.in2:=io.in.bits.in2
35	  alu.io.in3:=io.in.bits.in3
36	  alu.io.func:=io.in.bits.ctrl.alu_fn(4,0)
37	  val result=Module(new Queue(new WriteScalarCtrl,1,pipe=true))
38	  val result_br=Module(new Queue(new BranchCtrl,1,pipe=true))
39	  result.io.deq<>io.out
40	  result_br.io.deq<>io.out2br
41	  result.io.enq.bits:=0.U.asTypeOf(new WriteScalarCtrl)
42	  result.io.enq.bits.warp_id:=io.in.bits.ctrl.wid
43	  result.io.enq.bits.wb_wxd_rd:=alu.io.out
44	  result.io.enq.bits.reg_idxw:=io.in.bits.ctrl.reg_idxw
45	  result.io.enq.bits.wxd:=io.in.bits.ctrl.wxd
46	  if(SPIKE_OUTPUT){
47	    result.io.enq.bits.spike_info.get:=io.in.bits.ctrl.spike_info.get
48	    result_br.io.enq.bits.spike_info.get:=io.in.bits.ctrl.spike_info.get
49	  }
50	  io.in.ready := MuxLookup(io.in.bits.ctrl.branch, result_br.io.enq.ready & result.io.enq.ready)(Seq(
51	    B_B->result_br.io.enq.ready,
52	    B_N->result.io.enq.ready
53	  ))
54	
55	  result_br.io.enq.bits.wid:=io.in.bits.ctrl.wid
56	  result_br.io.enq.bits.new_pc:=io.in.bits.in3
57	  result_br.io.enq.bits.jump:=MuxLookup(io.in.bits.ctrl.branch,false.B)(Seq(B_B->alu.io.cmp_out,B_J->true.B,B_R->true.B))
58	
59	  result_br.io.enq.valid := io.in.valid && MuxLookup(io.in.bits.ctrl.branch, result.io.enq.ready)(Seq(
60	    B_B -> true.B, B_N -> false.B,
61	  ))
62	  result.io.enq.valid := io.in.valid && io.in.bits.ctrl.wxd && MuxLookup(io.in.bits.ctrl.branch, result_br.io.enq.ready)(Seq(
63	    B_B -> false.B, B_N -> true.B,
64	  ))
65	}
66	class vMULexe extends Module{
67	  val io = IO(new Bundle {
68	    val in = Flipped(DecoupledIO(new vExeData()))
69	    val out_x = DecoupledIO(new WriteScalarCtrl())
70	    val out_v = DecoupledIO(new WriteVecCtrl)
71	  })
72	  val mul=VecInit(Seq.fill(num_thread)(Module(new ArrayMultiplier(num_thread, xLen)).io))
73	  val result_x=Module(new Queue(new WriteScalarCtrl,1,pipe=true))
74	  val result_v=Module(new Queue(new WriteVecCtrl,1,pipe=true))
75	  (0 until num_thread).foreach(x=>{
76	    mul(x).in.bits.a := io.in.bits.in1(x)
77	    mul(x).in.bits.b := io.in.bits.in2(x)
78	    mul(x).in.bits.c := io.in.bits.in3(x)
79	    mul(x).in.bits.ctrl := io.in.bits.ctrl
80	    mul(x).in.bits.mask := io.in.bits.mask
81	    mul(x).in.valid:=io.in.valid
82	    result_v.io.enq.bits.wb_wvd_rd(x) := mul(x).out.bits.result
83	    mul(x).out.ready:=Mux(mul(x).out.bits.ctrl.wxd,result_x.io.enq.ready,result_v.io.enq.ready)
84	    when(io.in.bits.ctrl.reverse){
85	      mul(x).in.bits.a:=io.in.bits.in2(x)
86	      mul(x).in.bits.b:=io.in.bits.in1(x)
87	    }
88	  })
89	
90	
91	  result_v.io.enq.bits.warp_id:=mul(0).out.bits.ctrl.wid
92	  result_v.io.enq.bits.reg_idxw:=mul(0).out.bits.ctrl.reg_idxw
93	  result_v.io.enq.bits.wvd:=mul(0).out.bits.ctrl.wvd
94	  result_v.io.enq.bits.wvd_mask:=mul(0).out.bits.mask
95	  if (SPIKE_OUTPUT) {
96	    result_v.io.enq.bits.spike_info.get := mul(0).out.bits.ctrl.spike_info.get
97	    result_x.io.enq.bits.spike_info.get := mul(0).out.bits.ctrl.spike_info.get
98	  }
99	  result_x.io.enq.bits.warp_id:=mul(0).out.bits.ctrl.wid
100	  result_x.io.enq.bits.reg_idxw:=mul(0).out.bits.ctrl.reg_idxw
101	  result_x.io.enq.bits.wxd:=mul(0).out.bits.ctrl.wxd
102	  result_x.io.enq.bits.wb_wxd_rd:=mul(0).out.bits.result
103	
104	  result_v.io.enq.valid:=mul(0).out.valid&mul(0).out.bits.ctrl.wvd
105	  result_x.io.enq.valid:=mul(0).out.valid&mul(0).out.bits.ctrl.wxd
106	  io.in.ready:=mul(0).in.ready//Mux(io.in.bits.ctrl.wfd,result_v.io.enq.ready,Mux(io.in.bits.ctrl.wxd,result_x.io.enq.ready,true.B))
107	  io.out_v<>result_v.io.deq
108	  io.out_x<>result_x.io.deq
109	
110	}
