112	class TCCtrlv2(xLen: Int, depth_warp: Int) extends FPUv2.TCCtrl(xLen, depth_warp){
113	  val spike_info=if(SPIKE_OUTPUT) Some(new InstWriteBack) else None
114	}
115	class vTCexe extends Module{
116	  val io = IO(new Bundle {
117	    val in = Flipped(DecoupledIO(new vExeData()))
118	    val rm = Input(UInt(3.W))
119	    //val out_x = DecoupledIO(new WriteScalarCtrl())
120	    val out_v = DecoupledIO(new WriteVecCtrl)
121	  })
122	  val tensor = Module(new TensorCoreFP32(num_thread, tc_dim(0), tc_dim(1), tc_dim(2), new TCCtrlv2(xLen, depth_warp)))
123	
124	  val result_v=Module(new Queue(new WriteVecCtrl,1,pipe=true))
