556	    result.io.enq.bits.warp_id := io.in.bits.ctrl.wid
557	    result.io.enq.bits.reg_idxw := io.in.bits.ctrl.reg_idxw
558	    result.io.enq.bits.wvd := io.in.bits.ctrl.wvd
559	    result.io.enq.bits.wvd_mask := io.in.bits.mask
560	    result.io.enq.valid := io.in.valid & io.in.bits.ctrl.wvd & (!io.in.bits.ctrl.simt_stack)
561	
562	    result2simt.io.enq.bits.wid := io.in.bits.ctrl.wid
563	    result2simt.io.enq.bits.if_mask := ~(VecInit(alu.map({ x => x.cmp_out })).asUInt)
564	    result2simt.io.enq.valid := io.in.valid & io.in.bits.ctrl.simt_stack
565	
566	    if(SPIKE_OUTPUT){
567	      result.io.enq.bits.spike_info.foreach{ _ := io.in.bits.ctrl.spike_info.get }
568	    }
569	
570	    io.in.ready := Mux(io.in.bits.ctrl.simt_stack, result2simt.io.enq.ready, result.io.enq.ready)
571	  }
572	  //==========================================
573	  else{
574	    val maxIter = softThread / hardThread
575	
576	    val inReg = Reg(new vExeData2)
577	    val hardResult = VecInit.fill(softThread)(0.U(xLen.W))
578	    val resultReg = Reg(new WriteVecCtrl2)
579	    val simtReg = Reg(new vec_alu_bus2)
580	    val outFIFOReady = Mux(inReg.ctrl.simt_stack, result2simt.io.enq.ready, result.io.enq.ready)
581	
582	    val sendNS = WireInit(0.U(log2Ceil(maxIter+1).W))
583	    val sendCS = RegNext(sendNS)
584	    val send = Wire(Decoupled(UInt(0.W)))
585	    send.bits := DontCare
586	    val recv = Wire(Decoupled(UInt(0.W)))
587	    recv.bits := DontCare
588	
589	    switch(sendCS){
590	      is(0.U){
591	        when(io.in.fire){
592	          sendNS := sendCS +% 1.U
593	        }.otherwise{ sendNS := 0.U }
594	      }
595	      is((1 until maxIter).map{_.U}){
596	        when(send.fire){ sendNS := sendCS +% 1.U }.otherwise{ sendNS := sendCS }
597	      }
598	      is(maxIter.U){
599	        when(send.fire){
600	          when(io.in.fire){ // continuous flow
601	            sendNS := 1.U
602	          }.otherwise{
603	            sendNS := 0.U
604	          }
605	        }.otherwise{
606	          sendNS := sendCS
607	        }
608	      }
609	    }
610	
611	    switch(sendNS){
612	      is(0.U){
613	        inReg := 0.U.asTypeOf(inReg)
614	      }
615	      is(1.U){
616	        when(io.in.fire){
617	          inReg := io.in.bits
618	        }
619	      }
620	      is((2 to maxIter).map{_.U}){
621	        when(sendCS =/= sendNS){
622	          (0 until softThread).foreach { i =>
623	            if (i + hardThread < softThread) {
624	              inReg.in1(i) := inReg.in1(i + hardThread)
625	              inReg.in2(i) := inReg.in2(i + hardThread)
626	              inReg.in3(i) := inReg.in3(i + hardThread)
627	            }
628	            else {
629	              inReg.in1(i) := 0.U
630	              inReg.in2(i) := 0.U
631	              inReg.in3(i) := 0.U
632	            }
633	          }
634	        }
635	      }
636	    }
637	    send.valid := sendCS =/= 0.U
638	    send.ready := recv.ready
639	
640	    val recvNS = WireInit(0.U(log2Ceil(maxIter+1).W))
641	    val recvCS = RegNext(recvNS)
642	
643	    val recv_wvd = Reg(Bool())
644	    val recv_simt_stack = Reg(Bool())
645	
646	    switch(recvCS){
647	      is((0 until maxIter).map{_.U}){
648	        when(recv.fire){
649	          recvNS := recvCS +% 1.U
650	        }.otherwise{
651	          recvNS := recvCS // may never happen
652	        }
653	      }
654	      is(maxIter.U){
655	        when(outFIFOReady){ // continuous flow
656	          when(recv.fire){
657	            recvNS := 1.U
658	          }.otherwise{
659	            recvNS := 0.U
660	          }
661	        }.otherwise{
662	          recvNS := recvCS
663	        }
664	      }
665	    }
666	
667	    switch(recvNS){
668	      is(0.U){
669	        resultReg := 0.U.asTypeOf(resultReg)
670	        simtReg.if_mask := 0.U(softThread.W)
671	      }
672	      is((1 to maxIter).map{_.U}){
673	        when(recv.fire){
674	          (0 until softThread).foreach { i =>
675	            if (i + hardThread < softThread) {
676	              resultReg.wb_wvd_rd(i) := resultReg.wb_wvd_rd(i + hardThread)
677	            }
678	            else {
679	              resultReg.wb_wvd_rd(i) := hardResult(i + hardThread - softThread)
680	            }
681	            simtReg.if_mask := Cat(~(VecInit(alu.map({ x => x.cmp_out })).asUInt), simtReg.if_mask(softThread-1, softThread-hardThread))
682	          }
683	          when(recvNS===maxIter.U){
684	            //resultReg.wb_wvd_rd.foreach{ _ := 0.U }
685	            resultReg.warp_id := inReg.ctrl.wid
686	            resultReg.reg_idxw := inReg.ctrl.reg_idxw
687	            resultReg.wvd := inReg.ctrl.wvd
688	            resultReg.wvd_mask := inReg.mask
689	            if(SPIKE_OUTPUT){
690	              resultReg.spike_info.foreach{ _ := inReg.ctrl.spike_info.get }
691	            }
692	            simtReg.wid := inReg.ctrl.wid
693	            recv_wvd := inReg.ctrl.wvd
694	            recv_simt_stack := inReg.ctrl.simt_stack
695	          }
696	        }
697	      }
698	    }
699	    recv.ready := recvCS =/= maxIter.U || (recvCS===maxIter.U && outFIFOReady)
700	    recv.valid := send.valid
701	
702	    (0 until hardThread).foreach{ x =>
703	      alu(x).in1 := inReg.in1(x)
704	      alu(x).in2 := inReg.in2(x)
705	      alu(x).in3 := inReg.in3(x)
706	      alu(x).func := inReg.ctrl.alu_fn(4, 0)
707	      hardResult(x) := alu(x).out
708	      when(inReg.ctrl.reverse) {
709	        alu(x).in1 := inReg.in2(x)
710	        alu(x).in2 := inReg.in1(x)
711	      }
712	      when((inReg.ctrl.alu_fn === FN_VMANDNOT) | (inReg.ctrl.alu_fn === FN_VMORNOT) | (inReg.ctrl.alu_fn === FN_VMNAND) | (inReg.ctrl.alu_fn === FN_VMNOR) | (inReg.ctrl.alu_fn === FN_VMXNOR)) {
713	        when((inReg.ctrl.alu_fn === FN_VMANDNOT) | (inReg.ctrl.alu_fn === FN_VMORNOT)) {
714	          alu(x).in1 := (~inReg.in1(x))
715	          alu(x).func := Cat(3.U(4.W), inReg.ctrl.alu_fn(0))
716	        }.otherwise({
717	          when(inReg.ctrl.alu_fn === FN_VMXNOR) {
718	            alu(x).func := FN_XOR(4, 0)
719	          }
720	            .otherwise(alu(x).func := Cat(3.U(4.W), inReg.ctrl.alu_fn(0)))
721	          hardResult(x) := (~alu(x).out)
722	        })
723	      }
724	      when(inReg.ctrl.alu_fn === FN_VID) {
725	        hardResult(x) := Mux(sendCS===0.U, 0.U, (sendCS-1.U)*hardThread.U + x.U)
726	      }
727	      when(inReg.ctrl.alu_fn === FN_VMERGE) {
728	        hardResult(x) := Mux(inReg.mask(x), inReg.in1(x), inReg.in2(x))
729	      }
730	    }
731	    result.io.enq.valid := recvCS===maxIter.U && recv_wvd && !recv_simt_stack
732	    result2simt.io.enq.valid := recvCS===maxIter.U && recv_simt_stack
733	    result.io.enq.bits := resultReg
734	    result2simt.io.enq.bits := simtReg
735	
736	    io.in.ready := sendCS === 0.U || (sendCS===maxIter.U && outFIFOReady)
737	  }
738	  result.io.deq <> io.out
739	  result2simt.io.deq <> io.out2simt_stack
740	}
