742	class ctrl_fpu extends Bundle{
743	val ctrl=new CtrlSigs
744	val mask=Vec(num_thread,Bool())
745	}
746	class FPUexe(softThread: Int = num_thread, hardThread: Int = num_thread) extends Module {
747	    assert(softThread % hardThread == 0)
748	  val io = IO(new Bundle {
749	    val in = Flipped(DecoupledIO(new vExeData()))
750	    val rm = Input(UInt(3.W))
751	    val out_x = DecoupledIO(new WriteScalarCtrl())
752	    val out_v = DecoupledIO(new WriteVecCtrl)
753	  })
754	  class TestFPUCtrl(depth_warp: Int, num_thread: Int, SPIKE_OUTPUT: Boolean)
755	    extends FPUv2.utils.TestFPUCtrl(depth_warp, num_thread){
756	    val spike_info = if(SPIKE_OUTPUT) Some(new InstWriteBack) else None
757	  }
758	  val fpu = Module(new FPUv2.VectorFPU(8, 24, softThread, hardThread, new TestFPUCtrl(depth_warp, num_thread,SPIKE_OUTPUT=SPIKE_OUTPUT)))
759	  (0 until num_thread).foreach{ x =>
760	    fpu.io.in.bits.data(x).a := io.in.bits.in1(x)
761	    fpu.io.in.bits.data(x).b := io.in.bits.in2(x)
762	    fpu.io.in.bits.data(x).c := io.in.bits.in3(x)
763	    fpu.io.in.bits.data(x).rm := io.rm
764	    when(io.in.bits.ctrl.reverse){
765	      fpu.io.in.bits.data(x).a := io.in.bits.in2(x)
766	      fpu.io.in.bits.data(x).b := io.in.bits.in1(x)
767	    }
768	    fpu.io.in.bits.data(x).op := io.in.bits.ctrl.alu_fn
769	    when((io.in.bits.ctrl.alu_fn===FN_VFMADD)|(io.in.bits.ctrl.alu_fn===FN_VFMSUB)|(io.in.bits.ctrl.alu_fn===FN_VFNMADD)|(io.in.bits.ctrl.alu_fn===FN_VFNMSUB)){
770	      fpu.io.in.bits.data(x).op := io.in.bits.ctrl.alu_fn-10.U
771	      fpu.io.in.bits.data(x).a := io.in.bits.in1(x)
772	      fpu.io.in.bits.data(x).b := io.in.bits.in3(x)
773	      fpu.io.in.bits.data(x).c := io.in.bits.in2(x)
774	    }
775	  }
776	  fpu.io.in.bits.ctrl.wvd := io.in.bits.ctrl.wvd
777	  fpu.io.in.bits.ctrl.wxd := io.in.bits.ctrl.wxd
778	  fpu.io.in.bits.ctrl.regIndex := io.in.bits.ctrl.reg_idxw
779	  fpu.io.in.bits.ctrl.warpID := io.in.bits.ctrl.wid
780	  fpu.io.in.bits.ctrl.vecMask := io.in.bits.mask.asUInt
781	  fpu.io.in.valid := io.in.valid
782	  io.in.ready := fpu.io.in.ready
783	
784	  (0 until num_thread).foreach{ x =>
785	    io.out_v.bits.wb_wvd_rd(x) := fpu.io.out.bits.data(x).result(31,0)
786	  }
787	  if (SPIKE_OUTPUT) {
788	//    fpu.io.in.bits.ctrl.asInstanceOf(new TestFPUCtrl(depth_warp, num_thread,SPIKE_OUTPUT=SPIKE_OUTPUT)).spike_info.get := io.in.bits.ctrl.spike_info.get
789	    fpu.io.in.bits.ctrl.spike_info.get := io.in.bits.ctrl.spike_info.get // <- IDEA报错但能正常运行
790	    io.out_v.bits.spike_info.get := fpu.io.out.bits.ctrl.spike_info.get
791	    io.out_x.bits.spike_info.get := fpu.io.out.bits.ctrl.spike_info.get
792	  }
793	  io.out_x.bits.wb_wxd_rd := fpu.io.out.bits.data(0).result(31,0)
794	  io.out_v.bits.reg_idxw := fpu.io.out.bits.ctrl.regIndex
795	  io.out_x.bits.reg_idxw := fpu.io.out.bits.ctrl.regIndex
796	  io.out_v.bits.warp_id := fpu.io.out.bits.ctrl.warpID
797	  io.out_x.bits.warp_id := fpu.io.out.bits.ctrl.warpID
798	  io.out_v.bits.wvd_mask := VecInit(fpu.io.out.bits.ctrl.vecMask.asBools)
799	  io.out_v.bits.wvd := fpu.io.out.bits.ctrl.wvd
800	  io.out_x.bits.wxd := fpu.io.out.bits.ctrl.wxd
801	  io.out_v.valid := fpu.io.out.valid && fpu.io.out.bits.ctrl.wvd
802	  io.out_x.valid := fpu.io.out.valid && fpu.io.out.bits.ctrl.wxd
803	  fpu.io.out.ready := Mux(fpu.io.out.bits.ctrl.wvd, io.out_v.ready, io.out_x.ready)
804	}
