806	class SFUexe extends Module{
807	  val io = IO(new Bundle {
808	    val in = Flipped(DecoupledIO(new vExeData()))
809	    val rm = Input(UInt(3.W))
810	    val out_x = DecoupledIO(new WriteScalarCtrl())
811	    val out_v = DecoupledIO(new WriteVecCtrl)
812	  })
813	  val result_x=Module(new Queue(new WriteScalarCtrl,1,pipe=true))
814	  val result_v=Module(new Queue(new WriteVecCtrl,1,pipe=true))
815	  val s_idle :: s_busy :: s_finish :: Nil = Enum(3)
816	  val state=RegInit(s_idle)
817	
818	  val data_buffer=Queue(io.in,1)
819	  val mask=RegInit(0.U(num_thread.W))
820	  val num_grp = num_thread/num_sfu
821	  val mask_grp=Wire(Vec((num_grp),(Bool())))
822	  mask_grp.zipWithIndex.foreach(x=>x._1:=(mask(x._2*num_sfu+num_sfu-1,x._2*num_sfu)).orR)
823	  //val ctrl_fma=Module(new Queue(new ctrl_fpu,5,flow=true))
824	
825	
826	  val out_data=RegInit(VecInit(Seq.fill(num_thread)(0.U(xLen.W))))
827	
828	  val i_cnt = PriorityEncoder(mask_grp)
829	  val next_i_cnt = PriorityEncoder((mask_grp.asUInt & ( ~(1.U(num_thread.W)<<i_cnt)).asUInt))
830	  val i_valid = RegInit(false.B) // a better valid should change for each fire.
831	  val i_ctrl = data_buffer.bits.ctrl
832	  val i_data1 = WireInit(VecInit(Seq.fill(num_sfu)(0.U(xLen.W))))
833	  val i_data2 = WireInit(VecInit(Seq.fill(num_sfu)(0.U(xLen.W))))
834	  val i_data3 = WireInit(VecInit(Seq.fill(num_sfu)(0.U(xLen.W))))
835	  val i_mask = WireInit(VecInit(Seq.fill(num_sfu)(false.B)))
836	  for(i<-0 until num_grp) {
837	    when(i.asUInt===i_cnt){
838	      val i_1 = VecInit(data_buffer.bits.in1.slice(i*num_sfu,i*num_sfu+num_sfu))
839	      val i_2 = VecInit(data_buffer.bits.in2.slice(i*num_sfu,i*num_sfu+num_sfu))
840	      i_data1:=Mux(i_ctrl.reverse,i_2,i_1)
841	      i_data2:=Mux(i_ctrl.reverse,i_1,i_2)
842	      i_data3 := VecInit(data_buffer.bits.in3.slice(i*num_sfu,i*num_sfu+num_sfu))
843	      i_mask:=mask(i*num_sfu+num_sfu-1,i*num_sfu).asBools
844	    }}
845	
846	  val intDiv=VecInit(Seq.fill(num_sfu)(Module(new IntDivMod(xLen)).io))
847	  val floatDiv=VecInit(Seq.fill(num_sfu)(Module(new FloatDivSqrt).io))
848	  val alu_out_arbiter=VecInit(Seq.fill(num_sfu)(Module(new Arbiter(UInt(xLen.W),2)).io))
849	  alu_out_arbiter.foreach(x=>x.out.ready:=alu_out_arbiter.map(x=>x.out.valid).reduce(_&_))// i_ctrl.wfd & result_v.io.enq.ready | i_ctrl.wxd & result_x.io.enq.ready | !(i_ctrl.wxd&i_ctrl.wfd)
850	  //result_x.io.enq.bits:=Cat(out_data(0),i_ctrl.wxd,i_ctrl.reg_idxw,i_ctrl.wid).asTypeOf(new WriteScalarCtrl)
851	  //result_v.io.enq.bits:=Cat(out_data.asUInt,data_buffer.bits.mask.asUInt,i_ctrl.wfd,i_ctrl.reg_idxw,i_ctrl.wid).asTypeOf(new WriteVecCtrl)
852	  result_v.io.enq.bits.wvd_mask:=data_buffer.bits.mask
853	  result_v.io.enq.bits.wvd:=i_ctrl.wvd
854	  result_v.io.enq.bits.wb_wvd_rd:=out_data
855	  result_v.io.enq.bits.reg_idxw:=i_ctrl.reg_idxw
856	  result_v.io.enq.bits.warp_id:=i_ctrl.wid
857	  result_x.io.enq.bits.wxd:=i_ctrl.wxd
858	  result_x.io.enq.bits.warp_id:=i_ctrl.wid
859	  result_x.io.enq.bits.reg_idxw:=i_ctrl.reg_idxw
860	  result_x.io.enq.bits.wb_wxd_rd:=out_data(0)
861	  if (SPIKE_OUTPUT) {
862	    result_v.io.enq.bits.spike_info.get := i_ctrl.spike_info.get
863	    result_x.io.enq.bits.spike_info.get := i_ctrl.spike_info.get
864	  }
865	  result_x.io.enq.valid:=state===s_finish&i_ctrl.wxd
866	  result_v.io.enq.valid:=state===s_finish&i_ctrl.wvd
867	  val o_ready= i_ctrl.isvec&result_v.io.enq.ready | !i_ctrl.isvec & result_x.io.enq.ready
868	  for(i <- 0 until num_sfu)
869	  {
870	    alu_out_arbiter(i).in(0).bits := Mux(i_ctrl.alu_fn(0), intDiv(i).out.bits.r, intDiv(i).out.bits.q)
871	    alu_out_arbiter(i).in(1).bits := floatDiv(i).out.bits.result
872	    alu_out_arbiter(i).in(0).valid := intDiv(i).out.valid
873	    alu_out_arbiter(i).in(1).valid := floatDiv(i).out.valid
874	    intDiv(i).out.ready := alu_out_arbiter(i).in(0).ready
875	    floatDiv(i).out.ready := alu_out_arbiter(i).in(1).ready
876	
877	    intDiv(i).in.bits.a := 1.U
878	    intDiv(i).in.bits.d := 1.U
879	    floatDiv(i).in.bits.a :=(0x3f800000L).U(32.W)
880	    floatDiv(i).in.bits.b :=(0x3f800000L).U(32.W)
881	    floatDiv(i).in.bits.c :=(0x3f800000L).U(32.W)
882	    for(j <- 0 until num_grp){
883	      when(j.asUInt===i_cnt & i_mask(i)){
884	    intDiv(i).in.bits.a := i_data1(i)
885	    intDiv(i).in.bits.d := i_data2(i)
886	    floatDiv(i).in.bits.a := i_data1(i)
887	    floatDiv(i).in.bits.b := i_data2(i)
888	    floatDiv(i).in.bits.c := i_data3(i)}}
889	    intDiv(i).in.bits.signed := !i_ctrl.alu_fn(1)
890	    floatDiv(i).in.bits.rm := io.rm
891	    floatDiv(i).in.bits.op := i_ctrl.alu_fn(2, 0)
892	
893	    intDiv(i).in.valid := !i_ctrl.fp & i_valid
894	    floatDiv(i).in.valid := i_ctrl.fp & i_valid
895	  }
896	    val i_ready = Mux(i_ctrl.fp, floatDiv(0).in.ready, intDiv(0).in.ready)
897	  data_buffer.ready:=state===s_finish&o_ready
898	
899	  val alu_out_fire = alu_out_arbiter(0).out.fire
900	  switch(state){
901	    is(s_idle){
902	      when(io.in.fire){
903	        state:=s_busy
904	        mask:=io.in.bits.mask.asUInt
905	        i_valid:=true.B
906	      }
907	    }
908	    is(s_busy) {
909	      when(i_valid & i_ready){
910	        i_valid:=false.B
911	      }
912	      when(data_buffer.bits.ctrl.isvec & alu_out_fire) {
913	        for(i <- 0 until num_grp){
914	          when(i.asUInt===i_cnt){
915	            val next_mask=mask & (~((Fill(num_sfu,1.U(1.W))).asTypeOf(UInt(xLen.W)) << i*num_sfu)).asUInt
916	            mask := next_mask
917	            i_valid:=true.B
918	            for(j <- 0 until num_sfu) out_data(i*num_sfu+j) := alu_out_arbiter(j).out.bits
919	            when(!next_mask.orR){
920	              state := s_finish
921	              i_valid:=false.B
922	            }
923	          }
924	        }
925	
926	
927	      }.elsewhen(alu_out_fire) {
928	        out_data(0) := alu_out_arbiter(0).out.bits
929	        state := s_finish
930	        i_valid:=false.B
931	      }
932	
933	    }
934	    is(s_finish){
935	      when(o_ready){
936	        state:=s_idle
937	        out_data:=0.U.asTypeOf(Vec(num_thread,UInt(xLen.W)))
938	      }
939	    }
940	  }
941	
942	  io.out_v<>result_v.io.deq
943	  io.out_x<>result_x.io.deq
944	}
