  result_x.io.enq.valid:=mul(0).out.valid&mul(0).out.bits.ctrl.wxd
  io.in.ready:=mul(0).in.ready//Mux(io.in.bits.ctrl.wfd,result_v.io.enq.ready,Mux(io.in.bits.ctrl.wxd,result_x.io.enq.ready,true.B))
